{
  "requirements": [
    {
      "id": "F-01",
      "text": "The system shall ensure that only authenticated members can borrow or return books.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-01"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-02",
      "text": "The system shall log all user actions related to book borrowing and returning for auditability purposes.",
      "quality_axes": ["Trustworthiness|Responsibility"],
      "derived_from": ["TRU-02", "RES-03"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-03",
      "text": "The system shall implement data encryption for all member personal information stored.",
      "quality_axes": ["Trustworthiness|Sustainability"],
      "derived_from": ["TRU-03", "GRN-01"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-04",
      "text": "The system shall implement role-based access control for librarians and members.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-04"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-05",
      "text": "The system shall automatically notify members of overdue books via email.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-05"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-06",
      "text": "The system shall provide an accessible interface for all users, including those with disabilities.",
      "quality_axes": ["Responsibility"],
      "derived_from": ["RES-02"],
      "kaos_level": "tactical",
      "parent": null
    },
    {
      "id": "F-07",
      "text": "The system shall enforce a maximum of 5 simultaneous borrowing operations per member.",
      "quality_axes": ["Safety|Responsibility|Efficiency"],
      "derived_from": ["RES-04", "SAF-01", "EFF-02"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-08",
      "text": "The system shall allow members to update their personal information securely.",
      "quality_axes": ["Trustworthiness"],
      "derived_from": ["TRU-06"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-09",
      "text": "The system shall allow librarians to add or remove books with a latency of less than 3 seconds.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-06"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-10",
      "text": "The system shall maintain an uptime of 99.5% for consistent availability.",
      "quality_axes": ["Efficiency"],
      "derived_from": ["EFF-07"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-11",
      "text": "The system shall provide a backup mechanism to recover all transaction data in case of a failure.",
      "quality_axes": ["Safety"],
      "derived_from": ["SAF-04"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-12",
      "text": "The system shall track book availability and update the status in real-time.",
      "quality_axes": ["Efficiency|Safety"],
      "derived_from": ["EFF-03"],
      "kaos_level": "operational",
      "parent": null
    },
    {
      "id": "F-13",
      "text": "The library management system shall minimize energy consumption by using energy-efficient servers.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-01"],
      "kaos_level": "strategic",
      "parent": null
    },
    {
      "id": "F-14",
      "text": "The system shall provide digital notifications for overdue books to reduce paper waste.",
      "quality_axes": ["Sustainability"],
      "derived_from": ["GRN-03"],
      "kaos_level": "operational",
      "parent": null
    }
  ],
  "conflict_resolutions": [
    {
      "ids": ["EFF-02", "SAF-01"],
      "outcome": "merged",
      "favored_agent": null,
      "rationale": "The requirements were merged to enforce a maximum borrowing limit while allowing for efficiency through monitoring."
    },
    {
      "ids": ["TRU-03", "GRN-01"],
      "outcome": "merged",
      "favored_agent": null,
      "rationale": "The requirements were merged to explore energy-efficient encryption methods to balance security with sustainability."
    }
  ],
  "dropped": [
    {
      "id": "GRN-02",
      "reason": "Quarterly energy usage reports were not included in the final requirements."
    },
    {
      "id": "GRN-04",
      "reason": "The requirement to check the carbon footprint of each book was not adopted."
    },
    {
      "id": "GRN-05",
      "reason": "Implementing a recycling program for damaged books was not retained."
    },
    {
      "id": "GRN-06",
      "reason": "Tracking total energy savings through digital operations was not included."
    },
    {
      "id": "GRN-07",
      "reason": "Prioritizing the acquisition of e-books was not represented in the final requirements."
    },
    {
      "id": "EFF-01",
      "reason": "Response time for book searching was not retained."
    },
    {
      "id": "EFF-04",
      "reason": "Processing book returns within 1 second was not included."
    },
    {
      "id": "EFF-05",
      "reason": "Sending overdue notifications within 24 hours was redundant and merged."
    },
    {
      "id": "SAF-02",
      "reason": "Overdue notifications were not retained as a separate requirement."
    },
    {
      "id": "SAF-05",
      "reason": "Revoking borrowing privileges for members with outstanding overdue books was not included."
    },
    {
      "id": "SAF-06",
      "reason": "User authentication for borrowing features was integrated into TRU-01."
    },
    {
      "id": "SAF-07",
      "reason": "Logging transactions was merged into F-02 for auditability."
    },
    {
      "id": "RES-01",
      "reason": "Compliance with data protection regulations through encryption was merged with TRU-03."
    },
    {
      "id": "RES-06",
      "reason": "The feedback mechanism for reporting issues was not included."
    },
    {
      "id": "RES-07",
      "reason": "The annual report on usage statistics was not retained."
    },
    {
      "id": "TRU-02",
      "reason": "Logging borrowing transactions was merged into F-02."
    },
    {
      "id": "TRU-05",
      "reason": "The secure reporting and management of overdue books was merged into F-05."
    },
    {
      "id": "TRU-07",
      "reason": "Strong password policies were not retained."
    }
  ],
